import { getCombatStats } from './combat-stats.js';

const TAU=Math.PI*2, COLORS={orb:'#91e8ff',orbit:'#bdfcff',dagger:'#ffd38a',lightning:'#b8d7ff',frost:'#8de8cf',meteor:'#ff9b65',nova:'#d9b5ff',mine:'#ffcc69',beam:'#ff86dc',vortex:'#957cff',familiar:'#9fe7ff',aegis:'#fff0a3'};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const d2=(a,b)=>(a.x-b.x)**2+(a.y-b.y)**2;
const norm=(x,y)=>{const d=Math.hypot(x,y)||1;return{x:x/d,y:y/d}};
const angleDelta=(a,b)=>Math.atan2(Math.sin(a-b),Math.cos(a-b));
const levelOf=(g,id)=>clamp(Number(g.upgrades?.[id])||0,0,6);
const branchOf=(g,id)=>levelOf(g,id)>=6&&(g.evolutions?.[id]==='a'||g.evolutions?.[id]==='b')?g.evolutions[id]:null;
const alive=g=>(g.enemies||[]).filter(e=>!e.dead&&!(e.spawnDelay>0));
const sorted=(g,origin=g.player)=>alive(g).sort((a,b)=>d2(origin,a)-d2(origin,b)||(a.id||0)-(b.id||0));
const nearest=(g,range,origin=g.player)=>sorted(g,origin).find(e=>d2(origin,e)<=range*range)||null;
const strongest=g=>alive(g).sort((a,b)=>(Number(b.boss)-Number(a.boss))||(b.maxHp||b.hp)-(a.maxHp||a.hp)||(a.id||0)-(b.id||0))[0]||null;
const nextId=g=>{g._nextId=(g._nextId||1)+1;return g._nextId-1};
const hurt=(api,e,n,color)=>{if(e&&!e.dead&&n>0)api.damage(e,n,color)};
const lineDistance=(p,a,b)=>{const dx=b.x-a.x,dy=b.y-a.y,t=clamp(((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy||1),0,1);return Math.hypot(p.x-a.x-dx*t,p.y-a.y-dy*t)};

// Renderer contract: every item has shape, x/y, color, life/maxLife and layer.
// Optional geometry is toX/toY, radius, width, angle; kind/weapon distinguish silhouettes.
function effect(g,weapon,shape,data,life=.25,layer='above'){
  g.commonEffects.push({weapon,shape,phase:weapon==='aegis'?'shield':weapon==='meteor'||weapon==='mine'?'impact':'active',color:COLORS[weapon],life,maxLife:life,layer,...data});
}
function entity(g,weapon,kind,shape,data){
  const e={id:nextId(g),weapon,kind,shape,color:COLORS[weapon],layer:'actors',life:1,maxLife:1,...data};g.commonEntities.push(e);return e;
}

export function getCommonSpec(game,id){
  const rank=levelOf(game,id),branch=branchOf(game,id),level=branch?4:rank?1+(Math.min(rank,5)-1)/2:0,s=getCombatStats(game),D=s.damage,A=s.area,H=s.haste,U=s.duration;
  const specs={
    orb:{interval:(1.05-level*.09)/H,damage:(13+level*7)*D*.7,count:rank>=3?2:1,speed:430,life:1.7,radius:7*A},
    orbit:{damage:(9+level*5)*D,count:rank>=5?3:2,radius:76,hitRadius:13*A,speed:(2.1+level*.15)*H},
    dagger:{interval:(1.55-level*.11)/H,damage:(20+level*8)*D*.8,count:rank>=3?2:1,distance:235+level*25,hitRadius:10*A},
    lightning:{interval:(2.2-level*.16)/H,damage:(15+level*8)*D,count:3+Math.floor((Math.min(rank,5)-1)/2),range:190*A},
    frost:{interval:(6.3-level*.35)/H,damage:(8+level*4)*D,radius:(100+level*13)*A,life:(3.4+level*.45)*U},
    meteor:{interval:(5.8-level*.38)/H,damage:(35+level*13)*D,radius:(75+level*9)*A,delay:Math.max(.45,1.05-level*.1),trailWidth:28*A,trailLife:3.4*U},
    nova:{interval:(3.6-level*.28)/H,damage:(18+level*7)*D,radius:(125+level*15)*A},
    mine:{interval:(4.2-level*.28)/H,damage:(34+level*11)*D,radius:(62+level*7)*A,trigger:(66+level*5)*A,cap:rank>=5?4:3,burnLife:3*U},
    beam:{interval:(3-level*.22)/H,damage:(30+level*11)*D,length:420+level*35,width:(30+level*4)*A},
    vortex:{interval:(6-level*.3)/H,damage:(6+level*3)*D,radius:(115+level*14)*A,life:(3+level*.4)*U,pull:32},
    familiar:{interval:(1.2-level*.1)/H,damage:(12+level*6)*D,count:1,range:390+level*25,boltRadius:5*A},
    aegis:{interval:(10-level*.65)/H,amount:(.04+level*.04)*game.player.maxHp,life:4+level*.55,shieldRadius:38,shieldStyle:'base',retaliationRadius:145},
  };
  const q=specs[id];if(!q)return null;
  if(rank===6&&branch){
    if(id==='orb'&&branch==='a'){q.count=6;q.radius=10*A;q.damage*=.76;q.repeatPenalty=.55}else if(id==='orb'){q.count=1;q.damage*=2.45;q.speed=285;q.pierce=5;q.radius=18*A}
    if(id==='orbit'&&branch==='a'){q.count=4;q.radius=150;q.hitRadius=26*A;q.damage*=1.08}else if(id==='orbit'){q.count=5;q.radius=65;q.hitRadius=23.4*A;q.speed*=1.5;q.damage*=.8}
    if(id==='dagger'&&branch==='a'){q.count=5;q.hitRadius=16*A;q.spread=.25;q.damage*=.72}else if(id==='dagger'){q.count=2;q.hitRadius=18*A;q.cyclone=true;q.cycloneRadius=140;q.damage*=1.15}
    if(id==='lightning'&&branch==='a'){q.count=12;q.range=275*A;q.falloff=.035}else if(id==='lightning'){q.repeats=5;q.damage*=.85}
    if(id==='frost'&&branch==='a'){q.radius*=1.75;q.life*=1.55;q.damage*=.9}else if(id==='frost'){q.radius*=.85;q.damage*=1.7;q.interval*=.82}
    if(id==='meteor'&&branch==='a'){q.fireTrail=true;q.radius*=1.25;q.trailWidth*=1.7;q.damage*=1.12}else if(id==='meteor'){q.cluster=6;q.damage*=.48;q.radius*=.9}
    if(id==='nova'&&branch==='a'){q.radius*=1.85;q.interval*=1.22;q.slow=.62}else if(id==='nova'){q.radius*=.85;q.interval*=.48;q.damage*=.72}
    if(id==='mine'&&branch==='a'){q.chain=true;q.cap=6;q.count=2;q.radius*=1.2}else if(id==='mine'){q.burn=true;q.burnRadius=q.radius;q.damage*=.9}
    if(id==='beam'&&branch==='a'){q.sweep=true;q.width*=2.4;q.damage*=.8}else if(id==='beam'){q.width*=.75;q.damage*=2.25}
    if(id==='vortex'&&branch==='a'){q.radius*=1.85;q.damage*=.55;q.pull=48}else if(id==='vortex'){q.radius*=.9;q.damage*=1.55;q.pull=24}
    if(id==='familiar'&&branch==='a'){q.count=2;q.boltRadius*=1.4;q.damage*=.66;q.interval*=.78;q.speed=175}else if(id==='familiar'){q.damage*=2.35;q.interval*=1.35;q.speed=90;q.heavy=true;q.boltRadius*=2.2;q.splashRadius=60*A;q.splashBudget=.5}
    if(id==='aegis'&&branch==='a'){q.amount=game.player.maxHp*.25;q.shieldRadius=48;q.shieldStyle='bastion';q.life*=1.65;q.interval*=1.08}else if(id==='aegis'){q.amount=game.player.maxHp*.13;q.life*=.5;q.retaliate=true;q.retaliationRadius=190*A;q.shieldStyle='thorns';q.interval*=.7}
  }
  q.rank=rank;q.branch=branch;return q;
}

function fireOrb(g,q){
  const targets=sorted(g).filter(e=>d2(g.player,e)<620**2);if(!targets.length)return false;
  for(let i=0;i<q.count;i++){const t=targets[i%targets.length],a=Math.atan2(t.y-g.player.y,t.x-g.player.x)+(i-(q.count-1)/2)*.09;entity(g,'orb','homing','projectile',{x:g.player.x,y:g.player.y,vx:Math.cos(a)*q.speed,vy:Math.sin(a)*q.speed,speed:q.speed,radius:q.radius||7,damage:q.damage*(q.repeatPenalty&&i>=targets.length?q.repeatPenalty:1),targetId:t.id,pierce:q.pierce||0,life:q.life,maxLife:q.life,hitIds:new Set()})}return true;
}
function fireDagger(g,q){const t=nearest(g,680);if(!t)return false;const base=Math.atan2(t.y-g.player.y,t.x-g.player.x),spread=q.spread??.19;for(let i=0;i<q.count;i++){const a=base+(i-(q.count-1)/2)*spread,speed=480;entity(g,'dagger','boomerang','projectile',{x:g.player.x,y:g.player.y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,radius:q.hitRadius,damage:q.damage,phase:'outbound',travel:0,maxDistance:q.distance,curve:(i%2?1:-1)*(.32+Math.abs(i-(q.count-1)/2)*.08),returnSpeed:610,spin:0,cyclone:q.cyclone,cycloneRadius:q.cycloneRadius||105,life:4.8,maxLife:4.8,hitIds:new Set()})}return true}
function castLightning(g,q,api){let first=q.repeats?alive(g).filter(e=>d2(g.player,e)<=560**2).sort((a,b)=>(Number(b.boss)-Number(a.boss))||(b.maxHp||b.hp)-(a.maxHp||a.hp)||(a.id||0)-(b.id||0))[0]:nearest(g,560);if(!first)return false;const bonus=e=>(e.slow>0||e.frozen>0)?1.12:1;if(q.repeats){let from=g.player;for(let i=0;i<q.repeats;i++){hurt(api,first,q.damage*(1-i*.06)*bonus(first),COLORS.lightning);effect(g,'lightning','line',{x:from.x,y:from.y,toX:first.x,toY:first.y,width:3+i,phase:i?'echo':'strike',strength:1-i*.12},.16+i*.05);from={x:first.x+(i%2?10:-10),y:first.y}}return true}let current=first,from=g.player,seen=new Set;for(let i=0;i<q.count&&current;i++){hurt(api,current,q.damage*(1-i*(q.falloff??.07))*bonus(current),COLORS.lightning);effect(g,'lightning','line',{x:from.x,y:from.y,toX:current.x,toY:current.y,width:4,strength:1-i*.065},.18);seen.add(current.id);from=current;current=sorted(g,from).find(e=>!seen.has(e.id)&&d2(from,e)<=q.range*q.range)}return true}
function castZone(g,id,q){const t=nearest(g,520)||g.player;g.commonEntities=g.commonEntities.filter(e=>!(e.weapon===id&&e.kind==='zone'));g.commonEffects=g.commonEffects.filter(e=>!(e.weapon===id&&e.layer==='ground'));entity(g,id,'zone','circle',{x:t.x,y:t.y,radius:q.radius,damage:q.damage,tick:0,life:q.life,maxLife:q.life,pull:q.pull||0});effect(g,id,'circle',{x:t.x,y:t.y,radius:q.radius,width:4},q.life,'ground');return true}
function castMeteor(g,q,random){const t=nearest(g,600)||g.player,count=q.cluster||1;for(let i=0;i<count;i++){const a=random()*TAU,r=count===1?0:(35+random()*70),x=t.x+Math.cos(a)*r,y=t.y+Math.sin(a)*r,delay=q.delay+i*.14;entity(g,'meteor','meteor','projectile',{x,y,toX:x,toY:y-180,radius:q.radius,damage:q.damage,delay,fireTrail:q.fireTrail,trailWidth:q.trailWidth,trailLife:q.trailLife,life:delay+.08,maxLife:delay+.08});effect(g,'meteor','circle',{x,y,radius:q.radius,width:3,telegraph:true},delay,'ground')}return true}
function castNova(g,q,api){for(const e of alive(g))if(d2(g.player,e)<=(q.radius+(e.radius||0))**2){hurt(api,e,q.damage,COLORS.nova);if(q.slow)e.slow=Math.max(e.slow||0,e.boss?.08:e.elite?q.slow*.35:q.slow)}effect(g,'nova','ring',{x:g.player.x,y:g.player.y,radius:q.radius,width:12,expands:true},.55);return true}
function placeMine(g,q,random){const mines=g.commonEntities.filter(e=>e.weapon==='mine'&&e.kind==='mine');while(mines.length>=q.cap){const old=mines.shift();old.life=0;g.commonEntities=g.commonEntities.filter(e=>e!==old)}const a=random()*TAU,r=25+random()*45;entity(g,'mine','mine','construct',{x:g.player.x+Math.cos(a)*r,y:g.player.y+Math.sin(a)*r,radius:12,trigger:q.trigger,blast:q.radius,damage:q.damage,chain:q.chain,burn:q.burn,burnLife:q.burnLife,burnRadius:q.burnRadius,arming:.35,life:18,maxLife:18});return true}
function fireBeam(g,q,api){const t=nearest(g,720);if(!t)return false;const a=Math.atan2(t.y-g.player.y,t.x-g.player.x),count=q.sweep?3:1;for(let i=0;i<count;i++){const aa=a+(i-(count-1)/2)*.17,to={x:g.player.x+Math.cos(aa)*q.length,y:g.player.y+Math.sin(aa)*q.length};const impactPoints=[];for(const e of alive(g))if(lineDistance(e,g.player,to)<q.width/2+(e.radius||0)){hurt(api,e,q.damage/count,COLORS.beam);impactPoints.push({x:e.x,y:e.y});}effect(g,'beam','line',{impactPoints,x:g.player.x,y:g.player.y,toX:to.x,toY:to.y,angle:aa,radius:q.length,width:q.width},.3)}return true}

function ensureOrbit(g,dt,q,api){g._commonOrbit=(g._commonOrbit||0)+dt*q.speed;g._commonOrbitHits=g._commonOrbitHits||new Map;const liveIds=new Set(alive(g).map(e=>e.id));for(const id of g._commonOrbitHits.keys())if(!liveIds.has(id))g._commonOrbitHits.delete(id);let blades=g.commonEntities.filter(e=>e.weapon==='orbit');if(blades.length!==q.count){g.commonEntities=g.commonEntities.filter(e=>e.weapon!=='orbit');blades=[];for(let i=0;i<q.count;i++)blades.push(entity(g,'orbit','orbit','projectile',{x:g.player.x,y:g.player.y,radius:q.hitRadius,life:Infinity,maxLife:Infinity,slot:i}))}const cadence=branchOf(g,'orbit')==='b'?.3:.42;for(const b of blades){b.radius=q.hitRadius;const a=g._commonOrbit+b.slot*TAU/q.count;b.x=g.player.x+Math.cos(a)*q.radius;b.y=g.player.y+Math.sin(a)*q.radius;b.angle=a;for(const e of alive(g)){const ready=(g._commonOrbitHits.get(e.id)||0)<=g.time;if(ready&&d2(b,e)<(b.radius+(e.radius||0))**2){hurt(api,e,q.damage,COLORS.orbit);g._commonOrbitHits.set(e.id,g.time+cadence);effect(g,'orbit','circle',{x:e.x,y:e.y,radius:13},.14)}}}}
function ensureFamiliars(g,dt,q,api){let fs=g.commonEntities.filter(e=>e.weapon==='familiar'&&e.kind==='familiar');if(fs.length!==q.count){g.commonEntities=g.commonEntities.filter(e=>!(e.weapon==='familiar'&&e.kind==='familiar'));fs=[];for(let i=0;i<q.count;i++)fs.push(entity(g,'familiar','familiar','construct',{x:g.player.x,y:g.player.y,radius:q.heavy?19:13,slot:i,clock:.2,life:Infinity,maxLife:Infinity,heavy:q.heavy}))}for(const f of fs){f.heavy=!!q.heavy;f.radius=q.heavy?19:13;const a=(g.time*.8)+f.slot*TAU/q.count,tx=g.player.x+Math.cos(a)*(q.heavy?58:72),ty=g.player.y+Math.sin(a)*(q.heavy?58:72),n=norm(tx-f.x,ty-f.y),step=Math.min(Math.hypot(tx-f.x,ty-f.y),(q.speed||145)*dt);f.x+=n.x*step;f.y+=n.y*step;f.angle=a;f.clock-=dt;const t=nearest(g,q.range,f);if(t&&f.clock<=0){f.clock=q.interval;const aa=Math.atan2(t.y-f.y,t.x-f.x);f.fireTime=g.time;f.fireAngle=aa;entity(g,'familiar','bolt','projectile',{x:f.x,y:f.y,vx:Math.cos(aa)*460,vy:Math.sin(aa)*460,radius:q.boltRadius,damage:q.damage,splashRadius:q.splashRadius,splashBudget:q.splashBudget,heavy:q.heavy,targetId:t.id,life:1.2,maxLife:1.2,hitIds:new Set()})}}}
function retaliate(g,q,api){for(const e of alive(g))if(d2(g.player,e)<=(q.retaliationRadius+(e.radius||0))**2)hurt(api,e,q.amount*1.25*getCombatStats(g).damage,COLORS.aegis);effect(g,'aegis','ring',{phase:'retaliation',x:g.player.x,y:g.player.y,radius:q.retaliationRadius,width:15},.4)}
function updateAegis(g,dt,q,api){const s=g._commonAegis||(g._commonAegis={clock:0,life:0,last:0,retaliate:false});s.clock-=dt;s.life-=dt;const current=Math.max(0,Number(g.player.commonShield)||0);if(s.last>0&&current<=0){effect(g,'aegis','ring',{phase:'break',x:g.player.x,y:g.player.y,radius:38},.28);if(s.retaliate)retaliate(g,q,api);}if(s.life<=0&&current>0){effect(g,'aegis','ring',{phase:'break',x:g.player.x,y:g.player.y,radius:38},.28);g.player.commonShield=0;if(s.retaliate)retaliate(g,q,api)}if(s.clock<=0){g.commonEffects=g.commonEffects.filter(e=>!(e.weapon==='aegis'&&e.maxLife>1));g.player.commonShield=Math.min(g.player.maxHp*.25,q.amount);s.clock=q.interval;s.life=q.life;s.retaliate=!!q.retaliate;effect(g,'aegis','ring',{x:g.player.x,y:g.player.y,radius:q.shieldRadius,width:7,shieldStyle:q.shieldStyle,capacity:q.amount},q.life)}s.last=Math.max(0,Number(g.player.commonShield)||0)}

function explodeMine(g,m,api,chainBatch=false){if(m.exploded||m.life<=0)return;m.exploded=true;m.life=0;for(const e of alive(g))if(d2(m,e)<=(m.blast+(e.radius||0))**2)hurt(api,e,m.damage,COLORS.mine);effect(g,'mine','circle',{x:m.x,y:m.y,radius:m.blast,width:8},.35);if(m.burn)entity(g,'mine','burn','circle',{x:m.x,y:m.y,radius:m.burnRadius||m.blast*.75,damage:m.damage*.18,tick:0,life:m.burnLife||3,maxLife:m.burnLife||3});if(m.chain&&!chainBatch){const linked=g.commonEntities.filter(e=>e.weapon==='mine'&&e.kind==='mine'&&e.life>0&&!e.exploded&&d2(m,e)<=(m.blast*2.2)**2);for(const other of linked){effect(g,'mine','line',{phase:'chain',x:m.x,y:m.y,toX:other.x,toY:other.y,width:2},.16);explodeMine(g,other,api,true)}}}
// Expire every existing entity before any chain can inspect a later array entry.
function updateEntities(g,dt,api){for(const e of g.commonEntities)if(Number.isFinite(e.life))e.life-=dt;for(const e of g.commonEntities){if(e.life<=0&&!(e.kind==='meteor'&&!e.struck&&e.delay<=dt))continue;if(e.kind==='homing'||e.kind==='bolt'){let t=alive(g).find(x=>x.id===e.targetId)||nearest(g,600,e);if(t&&e.kind==='homing'){e.targetId=t.id;const n=norm(t.x-e.x,t.y-e.y);e.vx=e.vx*.87+n.x*e.speed*.13;e.vy=e.vy*.87+n.y*e.speed*.13}e.x+=e.vx*dt;e.y+=e.vy*dt}
    else if(e.kind==='boomerang'){const from={x:e.x,y:e.y};e.spin+=dt*18;if(e.phase==='outbound'){const turn=e.curve*dt,c=Math.cos(turn),s=Math.sin(turn),vx=e.vx;e.vx=vx*c-e.vy*s;e.vy=vx*s+e.vy*c;e.travel+=Math.hypot(e.vx,e.vy)*dt;const nx=e.x+e.vx*dt,ny=e.y+e.vy*dt,edge=28,w=g.world?.width||2400,h=g.world?.height||1800;if(e.travel>=e.maxDistance||nx<edge||ny<edge||nx>w-edge||ny>h-edge){e.hitIds=new Set();e.x=clamp(e.x,edge,w-edge);e.y=clamp(e.y,edge,h-edge);if(e.cyclone){e.phase='cyclone';e.cycloneTime=1.05;e.cycloneAngle=Math.atan2(e.y-g.player.y,e.x-g.player.x)}else e.phase='returning';if(nx<edge||ny<edge||nx>w-edge||ny>h-edge){const inward=norm(g.player.x-e.x,g.player.y-e.y),speed=Math.hypot(e.vx,e.vy)||480;e.vx=inward.x*speed;e.vy=inward.y*speed}}}else if(e.phase==='cyclone'){e.cycloneTime-=dt;e.cycloneAngle+=dt*5.3;e.x=g.player.x+Math.cos(e.cycloneAngle)*e.cycloneRadius;e.y=g.player.y+Math.sin(e.cycloneAngle)*e.cycloneRadius;if(e.cycloneTime<=0){e.phase='returning';e.hitIds=new Set()}}else{const n=norm(g.player.x-e.x,g.player.y-e.y),desired=Math.atan2(n.y,n.x),current=Math.atan2(e.vy,e.vx),a=current+clamp(angleDelta(desired,current),-dt*9.5,dt*9.5);e.vx=Math.cos(a)*e.returnSpeed;e.vy=Math.sin(a)*e.returnSpeed}if(e.phase!=='cyclone'){e.x+=e.vx*dt;e.y+=e.vy*dt}if(e.phase==='returning'){const w=g.world?.width||2400,h=g.world?.height||1800,tx=e.x-from.x,ty=e.y-from.y,l2=tx*tx+ty*ty,t=l2?clamp(((g.player.x-from.x)*tx+(g.player.y-from.y)*ty)/l2,0,1):0;e.x=clamp(e.x,28,w-28);e.y=clamp(e.y,28,h-28);if(Math.hypot(g.player.x-(from.x+tx*t),g.player.y-(from.y+ty*t))<=g.player.radius+18)e.life=0}}
    else if(e.kind==='meteor'&&e.delay!=null){e.delay-=dt;if(e.delay<=0&&!e.struck){e.struck=true;for(const x of alive(g))if(d2(e,x)<=(e.radius+(x.radius||0))**2)hurt(api,x,e.damage,COLORS.meteor);effect(g,'meteor','circle',{x:e.x,y:e.y,radius:e.radius,width:12},.45);if(e.fireTrail)entity(g,'meteor','burn','line',{x:e.x-150,y:e.y-110,toX:e.x,toY:e.y,radius:e.trailWidth,damage:e.damage*.16,tick:0,life:e.trailLife,maxLife:e.trailLife});e.life=0}}
    else if(e.kind==='mine'){e.arming-=dt;if(e.arming<=0&&alive(g).some(x=>d2(e,x)<=(e.trigger+(x.radius||0))**2))explodeMine(g,e,api)}
    else if(e.kind==='zone'||e.kind==='burn'){e.tick-=dt;if(e.weapon==='vortex'){for(const x of alive(g)){if(d2(e,x)>e.radius**2||x.boss)continue;const n=norm(e.x-x.x,e.y-x.y),scale=x.elite?.25:1;x.x+=n.x*e.pull*scale*dt;x.y+=n.y*e.pull*scale*dt}}if(e.tick<=0){e.tick=.5;for(const x of alive(g)){const inside=e.shape==='line'?lineDistance(x,e,{x:e.toX,y:e.toY})<=e.radius+(x.radius||0):d2(e,x)<=(e.radius+(x.radius||0))**2;if(!inside)continue;if(e.weapon==='frost'){x.poisonEffects=x.poisonEffects||[];let poison=x.poisonEffects.find(p=>p.sourceId===e.id);if(!poison){poison={sourceId:e.id,damage:e.damage,remaining:2};x.poisonEffects.push(poison)}poison.damage=e.damage;poison.remaining=2;x.poisonTick=Math.min(x.poisonTick??0,.55)}else hurt(api,x,e.damage,COLORS[e.weapon])}}}
    if(e.life<=0)continue;if(['homing','bolt','boomerang'].includes(e.kind)){for(const x of alive(g))if(!e.hitIds.has(x.id)&&d2(e,x)<=(e.radius+(x.radius||0))**2){hurt(api,x,e.damage,COLORS[e.weapon]);if(e.splashRadius){const others=alive(g).filter(other=>other.id!==x.id&&d2(x,other)<=(e.splashRadius+(other.radius||0))**2);const each=e.damage*(e.splashBudget||0)/Math.max(1,others.length);for(const other of others)hurt(api,other,each,COLORS[e.weapon]);effect(g,e.weapon,'circle',{phase:'splash',x:x.x,y:x.y,radius:e.splashRadius,width:5},.25)}e.hitIds.add(x.id);effect(g,e.weapon,'circle',{x:e.x,y:e.y,radius:e.radius*2,width:3},.18);if(e.kind!=='boomerang'){if(e.pierce>0)e.pierce--;else e.life=0}break}}
  }
  g.commonEntities=g.commonEntities.filter(e=>e.life>0);for(const e of g.commonEffects)e.life-=dt;g.commonEffects=g.commonEffects.filter(e=>e.life>0).slice(-180)
}

export function updateCommonAbilities(game,dt,api){
  if(!game||!game.player||!api?.damage)return;game.commonEntities=game.commonEntities||[];game.commonEffects=game.commonEffects||[];game.evolutions=game.evolutions||{};game._commonClocks=game._commonClocks||{};const random=typeof api.random==='function'?api.random:()=>.5;
  if(game.phase&&game.phase!=='playing')return;
  updateEntities(game,dt,api);
  const orbit=getCommonSpec(game,'orbit');if(levelOf(game,'orbit'))ensureOrbit(game,dt,orbit,api);else game.commonEntities=game.commonEntities.filter(e=>e.weapon!=='orbit');
  const familiar=getCommonSpec(game,'familiar');if(levelOf(game,'familiar'))ensureFamiliars(game,dt,familiar,api);else game.commonEntities=game.commonEntities.filter(e=>e.weapon!=='familiar');
  const aegis=getCommonSpec(game,'aegis');if(levelOf(game,'aegis'))updateAegis(game,dt,aegis,api);
  const casts={orb:(q)=>fireOrb(game,q),dagger:q=>fireDagger(game,q),lightning:q=>castLightning(game,q,api),frost:q=>castZone(game,'frost',q),meteor:q=>castMeteor(game,q,random),nova:q=>castNova(game,q,api),mine:q=>{for(let i=0;i<(q.count||1);i++)placeMine(game,q,random);return true},beam:q=>fireBeam(game,q,api),vortex:q=>castZone(game,'vortex',q)};
  for(const [id,cast] of Object.entries(casts)){if(!levelOf(game,id))continue;const q=getCommonSpec(game,id);game._commonClocks[id]=(game._commonClocks[id]??.15)-dt;if(game._commonClocks[id]<=0&&cast(q))game._commonClocks[id]=q.interval}
}
